  "source": "def investigate(context, acquire):
    table = {}
    high = 0
    stack = []
    for action in context['actions']:
        op = action['op']
        if op == 'begin':
            stack.append((dict(table), high))
        elif op == 'commit':
            stack.pop()
        elif op == 'rollback':
            table, high = stack.pop()
        elif op == 'put':
            ident = action['id']
            table[ident] = True
            if ident > high:
                high = ident
        elif op == 'delete':
            table.pop(action['id'], None)
    return high + 1
